var leaf=AssetDatabase.LoadAssetAtPath<Material>("Assets/AthenHill/Art/HeroTree/leaves.mat");
var one=new Material(leaf); var two=new Material(leaf);
one.SetFloat("_WardIndirectTranslucency",0); two.SetFloat("_WardIndirectTranslucency",.25f);
Undo.IncrementCurrentGroup(); int group=Undo.GetCurrentGroup();
try {
var objects=new UnityEngine.Object[]{one,two};
var prop=MaterialEditor.GetMaterialProperties(objects).Single(p=>p.name=="_WardIndirectTranslucency");
if(!prop.hasMixedValue)throw new Exception("Mixed material values not represented");
Undo.RecordObjects(objects,"Verify Ward material property Undo");
prop.floatValue=.15f; Undo.FlushUndoRecordObjects();
if(Mathf.Abs(one.GetFloat(prop.name)-.15f)>.0001f || Mathf.Abs(two.GetFloat(prop.name)-.15f)>.0001f)throw new Exception("Multi-material edit failed");
Undo.RevertAllDownToGroup(group);
if(Mathf.Abs(one.GetFloat(prop.name))>.0001f || Mathf.Abs(two.GetFloat(prop.name)-.25f)>.0001f)throw new Exception("Material Undo did not restore both values");
return new { multiEdit=true, mixedValue=true, undoRestored=true, sourceValue=leaf.GetFloat(prop.name), sceneDirty=UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene().isDirty };
} finally { UnityEngine.Object.DestroyImmediate(one);UnityEngine.Object.DestroyImmediate(two); }
